/*==========================
    PAGE
==========================*/

@page{
    size:A4;
    margin:10mm;
}

body{
    font-family:Arial, Helvetica, sans-serif;
    font-size:11px;
    color:#000;
}

.page{
    width:100%;
}


/*==========================
    TABLES
==========================*/

table{
    width:100%;
    border-collapse:collapse;
}

table td,
table th{
    border:1px solid #000;
    padding:4px;
    vertical-align:top;

}


/*==========================
    HEADER
==========================*/

.header-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border: 1px double #000 !important;
    border-bottom: none !important;
}

.header-table td{
    border:1px solid #9b9b9b;
    padding:14px;
    height:150px;
    border-bottom: none !important;
}

.logo-cell{
    text-align:center;
    vertical-align:middle;
    border-right: none !important;
}

.logo-cell img{
    width:75px;
    height:75px;
    /*object-fit:contain;*/
    margin-left:30px;
    margin-top:60px;
}

.company-cell{
    /*vertical-align:top;*/
    border-left: none !important;
    border-right: none !important;
}

.company-name{
    font-family:Arial, Helvetica, sans-serif;
    font-size:18px;
    font-weight:700;
    margin-bottom:6px;
    margin-top:36px;
    margin-left:30px;
}

.company-address{
    font-family:Arial, Helvetica, sans-serif;
    font-size:12px;
    margin-bottom:6px;
    margin-left:30px;
    /*line-height:18px;*/
}

.title-cell{
    position:relative;
    vertical-align:bottom;
    text-align:right;
    padding-right:12px;
    padding-bottom:12px;
    border-left: none !important;
}

.invoice-title{
    position:absolute;
    right:10px;
    bottom:10px;
    font-size:30px;
    font-weight:500;
    font-family:Arial, Helvetica, sans-serif;
    white-space:nowrap;
}


/*==========================
    INVOICE DETAILS
==========================*/


.details-table{
    border-top:none !important;
}

.details-table td{
    font-size:11px;
}

.label{
    width:40%;
    font-weight:bold;
}

.value{
    width:60%;
}


/*==========================
    BILL / SHIP
==========================*/

.party-table{
    margin-top:-1px;
    width:100%;
}

.party-table th{
    background:#d9d9d9;
    font-size:12px;
    text-align:left;
    font-weight:bold;
}

.party-table td{
    height: auto !important;
    font-size:12px;
    line-height:14px;
}

.party-name{
    font-size:13px;
    font-weight:bold;
    margin-bottom:6px;
}


/*==========================
    ITEMS
==========================*/

.items-table{
    margin-top:-1px;
}

.items-table thead th{
    background:#d9d9d9;
    text-align:center;
    font-size:12px;
    font-weight:bold;
    margin-bottom:-50px !important;
}

.items-table tbody td{
    font-size:12px;
}

.items-table tbody tr{
    height:28px;
}

.item-row td {
    border: 1px solid #000;
}

.blank-row td {
    border-top: none !important;
    border-bottom: none !important;
    height: 18px;
}

/* Keep left and right borders */
.blank-row td:first-child {
    border-left: 1px solid #000 !important;
}

.blank-row td:last-child {
    border-right: 1px solid #000 !important;
}

/* Bottom border ONLY on the last blank row */
.blank-row:last-child td {
    border-bottom: 1px solid #000 !important;
}

/* If there are already 10 or more actual items,
   put bottom border on the 10th/final displayed row */
.item-row:last-child td {
    border-bottom: 1px solid #000;
}

.center{
    text-align:center;
}

.right{
    text-align:right;
}


/*==========================
    FOOTER
==========================*/

.bottom-table{
    margin-top:-1px;
    height: auto !important;
}

.bank-section{
    height: auto !important;
    line-height:20px;
    font-size:12px;
}

.tax-section {
    padding: 0;
    position: relative;
    border-bottom: 1px solid #000 !important; /* first border */
}

.tax-section::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 105px; /* second border moves upward */
    border-bottom: 1px solid #000;
}

.amount-title{
    /*font-weight:bold;*/
    margin-bottom:4px;
}

.amount-words{
    min-height:40px;
    line-height: 0.4;
    font-style: italic;
    font-size:14px;
}


/*==========================
    TAX TABLE
==========================*/

.tax-table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
}

.tax-table tr {
    margin: 0;
    padding: 0;
    line-height: 3;
}

.tax-table td {
    padding: 0 !important;
    margin: 0;
    line-height: 1.5;
    vertical-align: middle;
}

.grand-total td{
    font-weight:bold;
    font-size:12px;
}


/*==========================
    SIGNATURE
==========================*/

.signature-box{
    /*border-top:1px solid #000;*/
    text-align:center;
    height: auto !important;
    font-weight:bold;
    padding-top:10px;
    margin-bottom:-8px;
}


/*==========================
    PRINT
==========================*/

.print-format{
    font-family:Arial, Helvetica, sans-serif;
    font-size:12px;
}

.print-format table{
    page-break-inside:auto;
}

.print-format tr{
    page-break-inside:avoid;
    page-break-after:auto;
}

thead{
    display:table-header-group;
}

tfoot{
    display:table-footer-group;
